# 10-shared: create both SGs
resource "aws_security_group" "app" { name = "app" vpc_id = var.vpc_id }
resource "aws_security_group" "db"  { name = "db"  vpc_id = var.vpc_id }
resource "aws_vpc_security_group_ingress_rule" "db_from_app" {
  security_group_id            = aws_security_group.db.id
  referenced_security_group_id = aws_security_group.app.id
  from_port = 5432
  to_port   = 5432
  ip_protocol = "tcp"
}

# old stack
removed {
  from = aws_s3_bucket.assets
  lifecycle { destroy = false }
}

# new stack
import {
  to = module.storage.aws_s3_bucket.this
  id = "acme-assets"
}
